do $pre$ declare h clued_control.current_head;c clued_control.execution_current;a clued_control.gate_attempts;b clued_control.execution_binding;budget clued_control.execution_events;rc clued_control.execution_events; amendment_raw text:=convert_from(decode('','base64'),'UTF8');begin
