 if h.sequence<>10 or h.generation_id<>'ctrgen_48100437d24e448ba01c542ebe1290da' or h.revoked or c.sequence<>119 or c.active_ga_id<>'ga_32daa5daf52c4deb8e893c25b08eff38' or c.pending_budget_sequence is not null or c.charged_seconds<>11706 or c.charged_evidence_bytes<>2604247987 or a.phase<>'PENDING' or a.sequence<>0 or a.container_id is not null or a.decision is not null or a.receipt_raw is not null or a.revoked or a.ga_sha256<>'68afb1e6dc1367729cd6864b9ba9b5d846ab123ff5539d7a646f7fa1df988f78' or a.budget_sequence<>117 or a.ga->>'control_trust_root_generation'<>'ctrgen_48100437d24e448ba01c542ebe1290da' or exists(select 1 from clued_control.execution_events e where e.root_id='ctr_414bd3c724264a83894b0c55cf2ab878' and e.sequence>119) then raise exception 'ROOT10_SCOPE_EXACT_PREIMAGE_REQUIRED'; end if;
